using System.Data;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Mappers;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.DataManagment.Services;public class ImagenAdministracionDataService:IImagenAdministracionDataService {private readonly IUnitOfWork _uow;public ImagenAdministracionDataService(IUnitOfWork uow)=>_uow=uow;public async Task<ImagenDataModel> CrearAsync(ImagenDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{await ValidarPrincipal(model.id_producto,null,model.es_principal,ct);var entity=ImagenDataMapper.ToEntity(model);await _uow.ImagenRepository.AgregarAsync(entity,ct);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);return ImagenDataMapper.ToDataModel(entity);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}public async Task<ImagenDataModel?> ActualizarAsync(ImagenDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=await _uow.ImagenRepository.ObtenerParaActualizarAsync(model.id_imagen,ct);if(entity is null){await _uow.RollbackTransactionAsync(ct);return null;}await ValidarPrincipal(model.id_producto,model.id_imagen,model.es_principal,ct);ImagenDataMapper.ApplyToEntity(model,entity);_uow.ImagenRepository.Actualizar(entity);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);return ImagenDataMapper.ToDataModel(entity);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}private async Task ValidarPrincipal(int producto,int? excluir,string indicador,CancellationToken ct){if(indicador!="S")return;var imagenes=await _uow.ImagenRepository.ObtenerPorProductoAsync(producto,ct);if(imagenes.Any(x=>x.es_principal=="S"&&x.id_imagen!=excluir))throw new InvalidOperationException("El producto ya tiene una imagen principal.");}}
